package com.fakelegacy.order.pricing;

import java.math.BigDecimal;

public class VolumeDiscountStep extends AbstractDiscountStep {

    @Override
    protected boolean appliesTo(LineDraft line) {
        return super.appliesTo(line) && line.getQuantity() >= 5;
    }

    @Override
    protected BigDecimal compute(LineDraft line, String tier) {
        return line.gross().subtract(line.getDiscountTier()).multiply(PricingConstants.VOLUME_RATE);
    }

    @Override
    protected void store(LineDraft line, BigDecimal amount) {
        line.setDiscountVolume(amount);
    }
}
